    casefiles = sorted((H / 'raw/cases').glob('*.json'))
    cases = [json.loads(p.read_text()) for p in casefiles]
    scored = [c for c in r4['comparisons'] if c['band_mm'] == 0.1]
    front = next((c for c in r4['contrasts'] if c['band_mm'] == 0.1 and 'Open minus Normal' in c['quantity']))
    angles = [c for c in r4['contrasts'] if c['band_mm'] == 0.1 and 'method' in c]
